// Generates supabase/migrations/20261027110100_seed_taxonomy.sql from docs/taxonomy.json (the same rows
// as docs/taxonomy.csv; the client seeds its cache from the same file, so slugs match).
// Usage: node scripts/generate-taxonomy-seed.mjs   (rewrites the migration; do not edit it by hand)
import { readFileSync, writeFileSync } from "node:fs";

export function buildSeed(rows) {
  const q = (v) => (v === null || v === undefined || v === "" ? "null" : `'${String(v).replace(/'/g, "''")}'`);
  const level1 = [];
  for (const r of rows) {
    const slug = r.slug.split("/")[0];
    if (!level1.some((l) => l.slug === slug)) level1.push({ slug, name: r.level1, firewall: r.sophos_firewall_category });
  }
  const lines = [
    "-- Phase H1: taxonomy seed (29 level 1, 71 level 2). Generated by scripts/generate-taxonomy-seed.mjs from",
    "-- docs/taxonomy.json; regenerate rather than edit by hand. Each category gets one dictionary event, level 1",
    "-- first, so dictionary-changes?since=0 hands clients the whole taxonomy in order.",
    "",
    "insert into public.categories (name, slug, sophos_firewall_category) values",
    level1.map((l) => `  (${q(l.name)}, ${q(l.slug)}, ${q(l.firewall)})`).join(",\n") + ";",
    "",
    "insert into public.categories (name, slug, parent_id, attention_level, sophos_firewall_category, description)",
    "select v.name, v.slug, p.id, v.attention::public.attention_level, v.firewall, v.description",
    "from (values",
    rows
      .map((r) => {
        const description = r.examples ? `${r.description} Examples: ${r.examples}.` : r.description;
        return `  (${q(r.level2)}, ${q(r.slug)}, ${q(r.slug.split("/")[0])}, ${q(r.attention_default)}, ${q(r.sophos_firewall_category)}, ${q(description)})`;
      })
      .join(",\n"),
    ") as v (name, slug, parent_slug, attention, firewall, description)",
    "join public.categories p on p.slug = v.parent_slug;",
    "",
    "insert into public.dictionary_events (category_id, type)",
    "select c.id, 'category_changed'",
    "from public.categories c",
    "join (values",
    [...level1.map((l) => l.slug), ...rows.map((r) => r.slug)].map((slug, i) => `  (${q(slug)}, ${i + 1})`).join(",\n"),
    ") as o (slug, ord) on o.slug = c.slug",
    "order by o.ord;",
    "",
    "update public.categories c set seq = e.seq from public.dictionary_events e where e.category_id = c.id;",
    "",
  ];
  return { sql: lines.join("\n"), level1: level1.length, level2: rows.length };
}

// Run as a script (also importable by tests).
if (process.argv[1]?.endsWith("generate-taxonomy-seed.mjs")) {
  const rows = JSON.parse(readFileSync(new URL("../docs/taxonomy.json", import.meta.url), "utf8"));
  const { sql, level1, level2 } = buildSeed(rows);
  writeFileSync(new URL("../supabase/migrations/20261027110100_seed_taxonomy.sql", import.meta.url), sql);
  console.log(`Seed written: ${level1} level-1 and ${level2} level-2 categories.`);
}
